import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BS2VDJqE.js";const p=JSON.parse('{"title":"Search modes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/search-modes.md","filePath":"guide/search-modes.md","lastUpdated":1795797533000}'),i={name:"guide/search-modes.md"};function d(n,e,s,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="search-modes" tabindex="-1">Search modes <a class="header-anchor" href="#search-modes" aria-label="Permalink to &quot;Search modes&quot;">​</a></h1><p>The search bar can look up words in four different ways. Tap the <strong>mode button</strong> — it sits at the right edge of the search bar, and also in the expanded search view next to the clear (✕) button — to cycle through them. The current mode is shown by its icon, and on long-press by a tooltip such as &quot;Search mode: Prefix&quot;. Your choice is saved and restored the next time you open Ciyue.</p><p>The four modes, in cycle order:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Icon</th><th>Matches</th><th>Needs the full-text index?</th></tr></thead><tbody><tr><td>Prefix (default)</td><td>⏮</td><td>Headwords <strong>starting with</strong> your query.</td><td>No</td></tr><tr><td>Suffix</td><td>⏭</td><td>Headwords <strong>ending with</strong> your query.</td><td>Yes</td></tr><tr><td>Multi-word</td><td>🔗</td><td>Headwords containing <strong>every</strong> term you type, not necessarily adjacent.</td><td>Yes</td></tr><tr><td>Full text</td><td>🔍</td><td>Text <strong>inside definitions</strong>, not just headwords.</td><td>Yes</td></tr></tbody></table><h2 id="prefix-—-the-default" tabindex="-1">Prefix — the default <a class="header-anchor" href="#prefix-—-the-default" aria-label="Permalink to &quot;Prefix — the default&quot;">​</a></h2><p>Headwords that begin with what you type, e.g. <code>app</code> → <code>apple</code>, <code>application</code>. This is the original Ciyue behaviour and needs no setup: it works as soon as a dictionary is loaded.</p><h2 id="suffix-—-a-reverse-dictionary" tabindex="-1">Suffix — a reverse dictionary <a class="header-anchor" href="#suffix-—-a-reverse-dictionary" aria-label="Permalink to &quot;Suffix — a reverse dictionary&quot;">​</a></h2><p>Headwords that <strong>end</strong> with your query, so you can look a word up by its tail. This is the reverse-dictionary / 倒序词典 idea: if you can only remember the ending — say you want a word ending in &quot;动&quot; (movement) but can&#39;t recall 翕动 — typing 动 lists 按兵不动, 摆动, 半自动, 暴动, 被动 … and you pick the one you meant.</p><p>Suffix matching is served by a reversed-headword column added to the full-text index, so it needs that index (see below).</p><h2 id="multi-word-—-combine-terms" tabindex="-1">Multi-word — combine terms <a class="header-anchor" href="#multi-word-—-combine-terms" aria-label="Permalink to &quot;Multi-word — combine terms&quot;">​</a></h2><p>Headwords that contain <strong>all</strong> the characters you type, in any order and not necessarily next to each other. Search <code>中国</code> (or <code>中 国</code>) and the suggestions include 中国 (adjacent, in order), 国中 (adjacent, reversed), 中国通 and 大秦景教流行中国碑 (both containing the adjacent pair 中国), and 中立国, 中华民国鄂州约法, 中华民国北伐铁血团 (with other characters in between). Every headword holds both characters, but they need not be adjacent or in order — an intent neither prefix nor suffix matching can express.</p><h2 id="full-text-—-search-the-definitions" tabindex="-1">Full text — search the definitions <a class="header-anchor" href="#full-text-—-search-the-definitions" aria-label="Permalink to &quot;Full text — search the definitions&quot;">​</a></h2><p>Matches your query <strong>inside the definitions</strong>, not just the headwords. Type a concept or a phrase and Ciyue lists every entry whose article mentions it, with a snippet of the surrounding text. This is the same engine as the standalone &quot;Search in definitions&quot; results, now available directly in the search bar.</p><h2 id="the-full-text-index" tabindex="-1">The full-text index <a class="header-anchor" href="#the-full-text-index" aria-label="Permalink to &quot;The full-text index&quot;">​</a></h2><p>Suffix, Multi-word and Full text all read from the <strong>full-text index</strong> that Ciyue builds per dictionary. Prefix does not use it.</p><p>When you first use one of those three modes, Ciyue starts building the index in the background — the same build the full-text page runs. Until an index is ready, the search bar shows a status row instead of results:</p><ul><li><strong>Building…</strong> — the index is being created; results appear once it finishes.</li><li><strong>Index not built</strong> — tap it to open the full-text page, where the build runs and reports progress.</li><li><strong>Index failed</strong> — tap it to retry from the full-text page.</li></ul><p>You can also build and manage every dictionary&#39;s index at once from <strong>Settings → Manage Dictionaries → the index-overview icon</strong>, which lists each dictionary&#39;s status, on-disk size and build / cancel / rebuild actions.</p><h2 id="the-search-pane-on-a-wide-window" tabindex="-1">The search pane on a wide window <a class="header-anchor" href="#the-search-pane-on-a-wide-window" aria-label="Permalink to &quot;The search pane on a wide window&quot;">​</a></h2><p>A landscape window wide enough for the split view has a column on the left. While its search box is empty the column shows your history; as soon as you type it shows the headwords that match, and keeps them on screen while you scroll. They are the same matches the drop-down offers, as a list to read rather than one to pick from.</p><p>The order follows the mode, which is what makes that list worth scanning:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Ordered by</th></tr></thead><tbody><tr><td>Prefix</td><td>The headword, the way a dictionary is</td></tr><tr><td>Suffix</td><td>The reversed headword, so entries that share an ending sit together — the order a reverse dictionary (倒序词典) uses</td></tr><tr><td>Multi-word</td><td>The headword</td></tr><tr><td>Full text</td><td>The entries that matched, each with its surrounding text</td></tr></tbody></table><p>The drop-down under the search bar stops at 30 matches per dictionary, because a drop-down is for picking one; the pane asks for 200, because there it is a list to read. Only prefix works without an index: the other three need the full-text index, and the pane reports its state instead of showing an empty column.</p><p><code>↑</code> / <code>↓</code> walk the list and show each word in the entry pane. <code>Ctrl</code>+<code>B</code> hides and shows the column.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./word-forms.html">Word-Form Lookup</a> — resolve inflected forms to their lemma.</li><li><a href="./getting-started.html">Getting Started</a> — add dictionaries.</li><li><a href="https://github.com/mumu-lhl/Ciyue/issues/824" target="_blank" rel="noreferrer">Issue #824</a> — the proposal that introduced search modes.</li></ul>',26)])])}const f=t(i,[["render",d]]);export{p as __pageData,f as default};
